"""Write a local development .env for the FATH backend.

Run from the backend directory; setup-dev.cmd does that for you. An existing
.env is never overwritten, and the generated secret key is never printed.
"""

import secrets
from pathlib import Path

ENV_PATH = Path(".env")

TEMPLATE = """\
# Local development settings, generated by setup-dev.cmd.
# For local use only - never commit this file or deploy with it.

DJANGO_DEBUG=True
DJANGO_SECRET_KEY={secret_key}
DJANGO_ALLOWED_HOSTS=localhost,127.0.0.1

# The Next.js dev server.
CORS_ALLOWED_ORIGINS=http://localhost:3000,http://127.0.0.1:3000

# DATABASE_URL is deliberately unset: Django then uses the SQLite file in this
# directory. Set it only when pointing a local run at Postgres.

# Mail is printed to the terminal instead of being sent anywhere.
EMAIL_BACKEND=django.core.mail.backends.console.EmailBackend
DEFAULT_FROM_EMAIL=FATH 3D <dev@localhost>
"""


def main():
    if ENV_PATH.exists():
        print("      .env already exists - leaving it untouched.")
        return 0

    ENV_PATH.write_text(
        TEMPLATE.format(secret_key=secrets.token_urlsafe(50)), encoding="utf-8"
    )
    print("      Wrote .env with a freshly generated secret key.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
